import { useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import * as Dialog from '@radix-ui/react-dialog';
import { ArrowDownToLine, ArrowRight, ArrowUpRight, BadgeCheck, Banknote, BookOpen, CheckCheck, ChevronDown, ChevronRight, CircleAlert, CircleCheck, Clock3, FileCheck2, FileText, FolderOpen, HelpCircle, History, IndianRupee, Layers3, LayoutDashboard, LoaderCircle, Menu, Plus, RefreshCw, Search, ShieldCheck, Sparkles, UploadCloud, X } from 'lucide-react';

type Item = Record<string, any>;
type View = 'overview' | 'documents' | 'ledger' | 'interest' | 'review' | 'audit';
const nav: { id: View; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'overview', label: 'Claim workspace', icon: LayoutDashboard }, { id: 'documents', label: 'Evidence library', icon: FolderOpen },
  { id: 'ledger', label: 'Invoices & payments', icon: Banknote }, { id: 'interest', label: 'Interest schedule', icon: IndianRupee },
  { id: 'review', label: 'Review & export', icon: FileCheck2 }, { id: 'audit', label: 'Activity log', icon: History },
];
const rupees = (value: unknown) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(value || 0));
const date = (value: unknown) => value ? new Date(String(value)).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Awaiting evidence';
const list = (value: any): Item[] => Array.isArray(value) ? value : [];
const statusLabel: Record<string, string> = { draft: 'Needs documents', review_required: 'Review required', ready: 'Ready for approval', approved: 'Approved' };
const needsReview = (status: string) => ['failed', 'unreadable', 'unsupported', 'needs_review', 'ocr_unavailable', 'parse_error', 'unstructured_review', 'extracted_needs_review'].includes(status);
const sourceStatus = (status: string) => ({parsed:'Parsed',reviewed:'Reviewed',superseded:'Replaced',ocr_unavailable:'Unreadable scan',parse_error:'Parse failed',unstructured_review:'Needs extraction review',extracted_needs_review:'Proposed facts · review required'}[status] || String(status || 'Uploaded').replaceAll('_',' '));

async function api(path: string, options?: RequestInit) {
  const response = await fetch(`/api${path}`, options);
  if (!response.ok) {
    let error;
    try { error = await response.json(); } catch { error = null; }
    const detail = error?.detail;
    throw new Error(typeof detail === 'string' ? detail : Array.isArray(detail) ? detail.map((x: Item) => x.msg).join('; ') : detail?.message || error?.message || `Request could not be completed (${response.status}).`);
  }
  return response.json();
}
const json = (body: Item, method = 'POST'): RequestInit => ({ method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: string }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Empty({ title, children, icon: Icon = FolderOpen }: { title: string; children: ReactNode; icon?: typeof FolderOpen }) { return <div className="empty"><span className="empty-icon"><Icon size={24} /></span><h3>{title}</h3><p>{children}</p></div>; }

export default function App() {
  const [view, setView] = useState<View>('overview');
  const [claim, setClaim] = useState<Item | null>(null);
  const [cases, setCases] = useState<Item[]>([]);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [modal, setModal] = useState(false);
  const [source, setSource] = useState<Item | null>(null);
  const [menu, setMenu] = useState(false);
  const [query, setQuery] = useState('');
  const [help, setHelp] = useState(false);
  const helpOpener = useRef<HTMLElement | null>(null);
  function showHelp(opener: HTMLElement) { helpOpener.current = opener; setHelp(true); }
  const [selectedInvoiceId, setSelectedInvoiceId] = useState('');
  const [invoiceFilter, setInvoiceFilter] = useState('all');
  const [modelPlanning, setModelPlanning] = useState(false);
  const [reviewer, setReviewer] = useState('');
  const [buyerConfirmed, setBuyerConfirmed] = useState(false);
  const [rateConfirmed, setRateConfirmed] = useState(false);
  const [approvalChecked, setApprovalChecked] = useState(false);
  const [resolutions, setResolutions] = useState<Record<string, { invoice: string; reason: string; source: string }>>({});
  const [sourceReviews, setSourceReviews] = useState<Record<string, { reason: string; replacement: string }>>({});
  const [invoiceEdits, setInvoiceEdits] = useState<Record<string, Item>>({});
  const fileRef = useRef<HTMLInputElement>(null);
  const sources = list(claim?.sources);
  const invoices = list(claim?.invoices);
  const payments = list(claim?.payments);
  const blockers = list(claim?.blockers);
  const totals = claim?.totals || {};
  const evaluated = claim?.evaluation?.metrics || claim?.evaluation;
  const synthetic = claim?.synthetic || claim?.is_demo || list(claim?.rates).some(r => r.synthetic) || sources.some(s => String(s.file).includes('synthetic')) || String(claim?.name || '').toLowerCase().includes('demo');

  useEffect(() => {
    setBusy('Loading workspace');
    api('/cases').then(async result => {
      const rows = list(result?.cases ?? result); setCases(rows);
      const saved = localStorage.getItem('bakaya.case');
      const active = rows.find(c => c.id === saved) || rows[0];
      if (active) setClaim(await api(`/cases/${active.id}`));
    }).catch(e => setError(e.message)).finally(() => setBusy(''));
  }, []);

  useEffect(() => {
    setBuyerConfirmed(Boolean(claim?.review?.buyer_confirmed));
    setRateConfirmed(Boolean(claim?.review?.rate_confirmed));
    setReviewer(claim?.review?.reviewer || claim?.approval?.reviewer || '');
    setApprovalChecked(false);
    setSourceReviews({});
  }, [claim?.id, claim?.revision]);

  useEffect(() => { setSource(null); setSelectedInvoiceId(''); }, [claim?.id]);

  async function perform(label: string, action: () => Promise<any>, message?: string) {
    setBusy(label); setError(''); setNotice('');
    try {
      const result = await action();
      if (result?.id) { setClaim(result); localStorage.setItem('bakaya.case', result.id); }
      if (message) setNotice(message);
      return result;
    } catch (e) { setError(e instanceof Error ? e.message : 'Something went wrong. Please try again.'); }
    finally { setBusy(''); }
  }

  async function loadDemo() {
    const result = await perform('Preparing synthetic case', () => api('/cases/demo', json({})), 'Synthetic records loaded. Review the open questions before approving.');
    if (result) { setCases(prev => [result, ...prev.filter(c => c.id !== result.id)]); setView('overview'); setBuyerConfirmed(false); setRateConfirmed(false); setApprovalChecked(false); setResolutions({}); }
  }
  async function selectCase(id: string) {
    await perform('Opening case', () => api(`/cases/${id}`));
    setResolutions({}); setBuyerConfirmed(false); setRateConfirmed(false); setApprovalChecked(false); setView('overview');
  }
  async function uploadFiles(files: FileList | null) {
    if (!files?.length || !claim) return;
    const form = new FormData(); Array.from(files).forEach(f => form.append('files', f));
    await perform('Reading documents', async () => {
      await api(`/cases/${claim.id}/upload`, { method: 'POST', body: form });
      return api(`/cases/${claim.id}/run`, json({ mode: 'fixed' }));
    }, 'Documents added and claim recalculated.');
    setApprovalChecked(false);
    if (fileRef.current) fileRef.current.value = '';
  }
  function openSource(ref: any, context?: Item) {
    if (view !== 'review') setView('documents');
    const id = typeof ref === 'string' ? ref : ref?.source_id || ref?.id;
    const found = sources.find(s => s.id === id || s.file === ref?.file);
    setSource({ ...found, ...typeof ref === 'object' ? ref : {}, file: found?.file || ref?.file || id || 'Source reference', text: ref?.text || ref?.excerpt || found?.text || 'This reference has no extracted text.', related_refs: context?.related_refs || context?.source_refs || [], field_sources: context?.field_sources || {}, record_context: context?.record_context || context });
  }
  function refs(item: Item) {
    let items = list(item.source_refs);
    if (!items.length && item.source_ref) items = [item.source_ref];
    if (!items.length && item.source_id) items = [{ source_id: item.source_id }];
    return items.length ? <button className="source-link" onClick={() => openSource(items[0], item)}><FileText size={12} /> View source{items.length > 1 ? ` (${items.length})` : ''} <ArrowUpRight size={11} /></button> : <span className="muted small">No source attached</span>;
  }

  async function saveReview() {
    if (!claim) return;
    const choices = Object.entries(resolutions).filter(([, r]) => r.invoice);
    await perform('Saving review decisions', () => api(`/cases/${claim.id}/review`, json({
      reviewer: reviewer.trim(), buyer_confirmed: buyerConfirmed, rate_confirmed: rateConfirmed,
      resolutions: choices.map(([paymentId, r]) => ({ payment_id: paymentId, allocations: [{ invoice_id: r.invoice, amount: String(payments.find(p => p.id === paymentId)?.amount || '0'), tds_amount: '0' }], reason: r.reason, source_id: r.source || undefined })),
      source_reviews: Object.entries(sourceReviews).filter(([, r]) => r.reason.trim().length >= 5).map(([sourceId, r]) => ({ source_id: sourceId, reason: r.reason, replacement_source_id: r.replacement })),
      invoice_updates: Object.entries(invoiceEdits).filter(([,r]) => Object.keys(r.fields || {}).length > 0).map(([invoiceId,r]) => ({invoice_id:invoiceId,source_id:r.source_id,reason:r.reason,fields:r.fields})),
    })), 'Review decisions saved. Verification has been rerun.');
    setResolutions({}); setSourceReviews({}); setInvoiceEdits({}); setApprovalChecked(false);
  }
  async function approve() {
    if (!claim) return;
    await perform('Recording your approval', () => api(`/cases/${claim.id}/approve`, json({ reviewer: reviewer.trim() })), 'Approval recorded. Your packet is ready to download.');
  }
  async function download() {
    if (!claim) return;
    await perform('Building claim packet', async () => {
      const response = await fetch(`/api/cases/${claim.id}/export`);
      if (!response.ok) { const result = await response.json().catch(() => null); throw new Error(result?.detail || 'Packet export failed.'); }
      const blob = await response.blob(); const url = URL.createObjectURL(blob);
"}

